T result = JsonConvert.DeserializeObject<T>(record);
return result;
}
Finally, we'll need to implement the write methods. For the sake of demonstration, we'll
write all of our records with a 60-minute sliding expiration time using the
DistributedCacheEntryOptions class. After that, we can simply pass in our key to the
cache, along with a serialized value (we'll be using JSON here, to take advantage of the
Newtonsoft.Json libraries) and our expiration options:
public async Task WriteString(string id, string value) {
DistributedCacheEntryOptions opts = new DistributedCacheEntryOptions()
{
SlidingExpiration = TimeSpan.FromMinutes(60)
};
await _cache.SetStringAsync(id, value, opts);
}
public async Task WriteRecord<T>(string id, T record) {
var value = JsonConvert.SerializeObject(record);
DistributedCacheEntryOptions opts = new DistributedCacheEntryOptions()
{
SlidingExpiration = TimeSpan.FromMinutes(60)
};
await _cache.SetStringAsync(id, value, opts);
}
And with that, our cache should be ready to use. Now, it's time to pull it all together in our
controller endpoints. For this, the interaction pattern will be the same across each method,
with the only difference being the type of read/write operation we perform on our cache. So
Let's look at how we'll implement our cache strategy:
[HttpGet("record/{id}")]
public async Task<ActionResult<DataRecord>> GetRecord(string id) {
var key = $"{id}record";
